import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    if platform.system() == "Windows":
        command = "wmic cpu get loadpercentage"
    else:
        command = "top -bn1 | grep 'Cpu(s)' | awk '{print $2}'"
    records = []
    start_time = time.time()
    while time.time() - start_time < duration:
        try:
            output = subprocess.check_output(command, shell=True, text=True)
            if platform.system() == "Windows":
                usage = output.strip().split('\n')[1].strip()
            else:
                usage = output.strip().replace('%', '')
            records.append({"timestamp": time.time(), "cpu_usage": usage})
        except subprocess.CalledProcessError:
            records.append({"timestamp": time.time(), "cpu_usage": "N/A"})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
        return None

