        raise OSError("Directory does not exist")
    python_files = glob.glob(os.path.join(test_dir, "*.py"))
    results = {}
    for file in python_files:
        start_time = time.time()
        try:
            subprocess.run(["python", file], check=True, capture_output=True)
            end_time = time.time()
