import threading
def task_func(file_list):
    if not isinstance(file_list, list) or len(file_list) == 0:
        return []
    processes = []
    for file_path in file_list:
        try:
            proc = subprocess.Popen(file_path, shell=True)
            processes.append(proc)
        except Exception:
            processes.append(None)
    while any(p is not None and p.poll() is None for p in processes):
        time.sleep(0.1)
    exit_codes = []
    for proc in processes:
        if proc is None:
            exit_codes.append(None)
        else:
            exit_codes.append(proc.returncode)
    return exit_codes

