import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.isfile(script_path):
        raise ValueError("Invalid script path")
    cpu_usage = 0.0
    memory_usage = 0
    proc = subprocess.Popen(['bash', script_path])
    start_time = time.time()
    while True:
        if time.time() - start_time > timeout:
            break
        try:
            p = psutil.Process(proc.pid)
            if p.status() == psutil.STATUS_ZOMBIE:
                break
            cpu_usage += p.cpu_percent(interval=0.0)
            memory_usage += p.memory_info().rss
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break
        time.sleep(0.1)
        if proc.poll() is not None:
            break
    if proc.poll() is None:
        proc.terminate()
        proc.wait()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

